"explanation": "アテンション機構（Attention Mechanism）とは、入力シーケンス内のすべてのトークン間の関連度（注意の重み）をスコアとして計算し、文脈理解に重要な部分を重点的に参照できる仕組み。「Attention is All You Need」（2017年）で提案されたSelf-Attentionが現代LLMの基盤。\n\nA：これはRNN（リカレントニューラルネットワーク）の説明。Transformerは全トークンを並列に処理できる点が革新。\nC：これはドロップアウト（Dropout）の説明であり、過学習対策の正則化手法。\nD：これはファインチューニングや転移学習の説明であり、アテンション機構とは別の概念。\n\n【頻出】Transformerの登場がLLMの飛躍的発展の鍵となった点を押さえる。Self-Attention・Multi-Head Attentionという用語も確認しておく。\n【関連】GPT（Decoder型）・BERT（Encoder型）のアーキテクチャ上の違いもTransformerの理解と合わせて整理するとよい。"
