"explanation": "Few-shotプロンプティングとは、プロンプト内にタスクの入出力例を数件（few shots）提示することで、モデルがパターンを把握して精度の高い回答を生成できるようにする手法。例を0件にするとZero-shot、1件はOne-shot。\n\nA：これはZero-shotプロンプティングの説明。事前例示なしでタスクを遂行させる。\nC：これはファインチューニングの説明。Few-shotはパラメータを更新しないIn-context Learningである点が重要。\nD：これはChain-of-Thought（CoT）プロンプティングの説明。思考ステップを明示させる手法。\n\n【頻出】Zero-shot・One-shot・Few-shotの違いと、ファインチューニングとの区別は頻出。プロンプト内での事例提示はパラメータ更新なしの「文脈内学習（In-context Learning）」である。\n【混同注意】Few-shotプロンプティングはモデルの重みを変えない。ファインチューニングは重みを更新する。この違いが最重要。"
