"explanation": "誤り。生成AIサービスの利用規約には、入力データの学習利用の有無・保存ポリシー・第三者共有の有無などに関する規定が含まれており、業務利用前に確認することが重要。各サービスにより扱いが異なる。\n\nA：正しい。例えばOpenAIのAPIはデフォルトで学習に使用しないが、ChatGPTの一部プランでは設定確認が必要。\nB：正しい。企業によるガイドライン策定は個人情報保護法への対応としても推奨される実務慣行。\nD：正しい。APIへの入力情報はサービス提供者のサーバーを経由するため、機密情報の取り扱いには慎重さが求められる。\n\n【頻出】生成AI利用における情報セキュリティ・個人情報保護の問題は、実務直結テーマとして出題頻度が高い。利用規約の確認・社内ルール整備が基本対応である。\n【関連】個人情報保護法（日本）・GDPR（EU）との整合性確認も企業コンプライアンス上の重要事項。"
