"explanation": "ディープフェイク（Deepfake）とは、深層学習（Deep Learning）と偽物（Fake）を組み合わせた語で、GANや拡散モデルを用いて実在の人物の顔・声・動作を精巧に偽造・置換する技術、またはその生成物。フィッシング詐欺・虚偽情報拡散・性的な合成画像による被害などの悪用が社会問題化している。\n\nA：バグの根本原因分析はデバッグツールの機能説明であり、ディープフェイクとは無関係。\nC：これは敵対的攻撃（Adversarial Attack）の説明。\nD：これは学習データからの個人情報復元を指す「モデル逆転攻撃（Model Inversion Attack）」の説明。\n\n【頻出】ディープフェイクは生成AIの社会的リスクとして試験頻出。「偽情報・なりすまし・選挙干渉」等との関連で問われる。\n【関連】ディープフェイク検出技術（Detection）や電子透かし（Watermarking）による対策も注目されている。"
