"answer": 1,
"explanation": "GPT（Generative Pre-trained Transformer）はDecoder型Transformerを採用し、前のトークン列から次のトークンを予測する自己回帰的な言語モデリングで事前学習される。その後RLHFによる指示追従調整が行われChatGPT等に展開された。\n\nA：Encoder型はBERT（Bidirectional Encoder Representations from Transformers）の説明。BERTは文章理解・分類に強く、GPTとは逆方向の情報参照を行う。\nC：誤り。GPTはテキスト生成モデルであり、DALL-Eは画像生成モデル。両者は別用途のモデルで機能を分担しているわけではない。\nD：誤り。GPTは大量テキストによる事前学習（Pre-training）が基盤であり、RLHFはその後の調整段階。\n\n【頻出】GPT（Decoder型）とBERT（Encoder型）のアーキテクチャの違いは頻出。「生成に強いDecoder」「理解・分類に強いEncoder」という対応で覚える。\n【関連】T5・BARTはEncoder-Decoder型（Seq2Seq）として翻訳・要約に活用される第3の形式として整理する。"
