"explanation": "GAN（敵対的生成ネットワーク）は、本物に近いデータを生成しようとするGenerator（生成器）と、本物か偽物かを見分けようとするDiscriminator（識別器）が互いに競い合うことで、生成器が高品質なデータを生成できるよう学習する手法（2014年、Ian Goodfellow提案）。\n\nA：これはオートエンコーダー（Autoencoder）またはVAE（変分オートエンコーダー）の説明。\nC：これは拡散モデル（Diffusion Model）の説明。GANとは異なるアーキテクチャ。\nD：これはMoE（Mixture of Experts）アーキテクチャの説明。GPT-4やGeminiに採用されているとされる構成。\n\n【頻出】GAN・拡散モデル・VAEの違いは生成AI基礎として出題される。「2モデルの競合」という特徴でGANを識別する。\n【関連】GANはフェイク動画・高解像度画像生成に広く使われたが、学習の不安定さ（モード崩壊等）から近年は拡散モデルへの移行が進んでいる。"
