"explanation": "MoE（Mixture of Experts）はモデル内に複数のエキスパート（サブネットワーク）を持ち、各入力トークンに対してゲーティング機構が関連するエキスパートのみを選択・活性化する構造。全パラメータを使わずに推論できるため、大規模モデルを計算効率よく実現できる。GPT-4・Gemini 1.5等で採用されているとされる。\n\nA：これはアンサンブル学習の説明。MoEは多数決で回答を決定するのではなく、入力ごとに使用するサブネットワークを切り替える。\nC：これはドメイン専門家からの知識獲得（Knowledge Engineering）の説明であり、MoEとは無関係。\nD：活性化関数の混在はMoEの定義に当たらない。\n\n【頻出】MoEは近年の大規模モデルの効率化手法として注目されており、試験でも問われるようになっている。「疎な活性化（Sparse Activation）」による計算効率向上がポイント。\n【関連】Dense（全パラメータ使用）モデルとSparse（一部のみ使用）なMoEモデルの対比で理解する。"
