"explanation": "誤り。AIの雇用への影響は一律ではなく、職種・産業・導入方法・社会制度によって大きく異なる。AIが一部業務を代替する一方で新たな職種を創出するという両面があり、「必ず失業率が上昇する」という断定は実証的に支持されていない。\n\nA：正しい。定型業務・文書処理などはAIによる自動化の影響を受けやすい。\nB：正しい。AIエンジニア・データサイエンティスト・プロンプトエンジニア等の新職種需要が増加している。\nC：正しい。OECDや各国政府もAI時代のリスキリング・アップスキリングを重要政策課題として位置づけている。\n\n【頻出】AIと雇用の関係は「代替」と「補完・創出」の両面から問われる。一方的な悲観論・楽観論ではなく、バランスのとれた理解が問われる。\n【関連】オックスフォード大学の研究（2013年）で「米国雇用の47%が自動化リスク」と試算されたことが議論の出発点となっている。"
