"explanation": "個人情報を含むデータをAI学習に利用する場合、個人情報保護法に基づき利用目的の特定・公表、必要に応じた本人同意の取得が求められる。学習目的が当初の利用目的と異なる場合は目的外利用として制限される。\n\nA：誤り。AIシステムを用いた個人情報の処理も個人情報保護法の適用対象。AIという手段が法適用を除外する根拠にはならない。\nC：誤り。生成AIが実在の人物に関する情報を出力する可能性があり、出力物にも個人情報が含まれうる。\nD：誤り。第三者提供の制限規定はAIサービス事業者にも適用される。学習データとして個人データを第三者に提供する場合も制限を受ける。\n\n【頻出】個人情報保護法とAI利用の関係は実務直結テーマ。「利用目的の特定・変更・第三者提供」の各場面でのルールを確認しておく。\n【関連】2022年の個人情報保護法改正で「仮名加工情報」「個人関連情報」が新設され、AIデータ利用との関係が注目されている。"
