"explanation": "EU AI規則ではAIが生成したコンテンツ（テキスト・画像・音声・動画）について、それがAI生成であることを開示する透明性義務が課されている。特にディープフェイクや選挙・政治関連コンテンツへの規制が強化されている。\n\nA：誤り。EU AI規則に加え、中国・米国の一部州でもAI生成コンテンツの表示義務に関する規制が整備されつつある。\nC：誤り。電子透かし（Watermarking）はAI生成コンテンツの識別手段の一つとして研究・実装が進んでおり、Google・Anthropic・OpenAI等が取り組んでいる。\nD：誤り。EU AI規則の透明性義務はエンドユーザー（一般利用者）への開示を含む。\n\n【頻出】AI生成コンテンツの透明性・開示義務は法規制テーマとして出題される。電子透かし・メタデータ付与等の技術的手段と法的義務の関係を理解する。\n【関連】C2PA（Content Credentials）はAIコンテンツの来歴・出所を証明する技術標準として業界標準化が進んでいる。"
