"explanation": "生成AIサービスの利用規約は法的拘束力を持つ契約であり、禁止事項（有害コンテンツの生成・不正利用・他者の権利侵害等）への違反はアカウント停止・利用停止・損害賠償請求等の法的リスクを伴う。\n\nA：誤り。各サービスの利用規約はデータ利用方針・禁止事項・責任範囲等において大きく異なる場合がある。業務利用前に各サービスの規約を確認することが重要。\nC：誤り。利用規約（Terms of Service）はサービス提供者と利用者間の法的拘束力ある契約であり、同意した時点で法的義務が発生する。\nD：誤り。同意なしの利用は契約違反となる場合があり、重要な禁止事項については内容確認が強く推奨される。\n\n【頻出】利用規約の重要性と確認すべきポイント（データ利用・禁止事項・責任範囲）は実務知識として問われる。\n【関連】企業でのAI利用において、利用規約・DPA（データ処理契約）・SLA（サービスレベル合意）の確認は法務・情報システム部門の基本業務。"
