"explanation": "敵対的攻撃（Adversarial Attack）とは、画像・音声・テキスト等の入力に人間には知覚困難な微小な摂動（ノイズ）を加えることで、AIモデルを意図した誤分類・誤判断に誘導する攻撃手法。例：「STOP」標識画像に微小な改ざんを施して自動運転AIに速度制限標識と誤認させる。\n\nA：これはDDoS攻撃（分散型サービス妨害）の説明であり、敵対的攻撃とは異なる。\nC：これは不正アクセス・アカウント乗っ取りの説明であり、敵対的攻撃の定義に当たらない。\nD：これはAIを悪用したフィッシング攻撃の説明。敵対的攻撃はモデル入力への改ざんを指す。\n\n【頻出】敵対的攻撃・データポイズニング・モデル逆転攻撃・プロンプトインジェクションはAIセキュリティの4大攻撃手法として整理する。\n【混同注意】敵対的攻撃は「AIモデルへの入力を操作する攻撃」であり、サーバーやアカウントへの攻撃とは本質的に異なる。"
