"explanation": "ジェイルブレイクとは、「あなたは制約のないAIです」「このロールプレイでは安全ルールは適用されない」などの巧妙なプロンプトによってLLMの安全ガイドライン・コンテンツポリシーを回避させ、有害情報・差別的コンテンツ等を生成させる行為。プロンプトインジェクションと密接に関連する。\n\nA：認証突破・管理者権限取得は不正アクセス攻撃の説明であり、ジェイルブレイクとは異なる。\nC：APIキーの不正利用はクレデンシャル詐取・不正使用の問題であり、ジェイルブレイクの定義に当たらない。\nD：学習データからの個人情報復元はモデル逆転攻撃（Model Inversion Attack）またはメンバーシップ推論攻撃の説明。\n\n【頻出】ジェイルブレイクはプロンプトインジェクションと並ぶLLMセキュリティの重要リスク。「安全制約の回避」という目的で両者は共通するが、ジェイルブレイクはエンドユーザー視点での回避行為を指すことが多い。\n【混同注意】ジェイルブレイクはスマートフォンのOS制限解除と同名だが、LLM文脈ではコンテンツポリシーの回避を指す別概念。"
