"explanation": "モデル逆転攻撃（Model Inversion Attack）とは、AIモデルへの入出力の観察・分析を通じて、そのモデルの学習に使用された個人情報・機密データ（顔画像・医療データ等）を復元・推定する攻撃。プライバシー侵害リスクの観点から重要な脅威。\n\nA：モデルのアーキテクチャ・重みの推定・複製はモデル抽出攻撃（Model Extraction Attack）またはモデルスティーリングの説明。\nC：入力の微細な改ざんによる誤判断誘導は敵対的攻撃（Adversarial Attack）の説明。\nD：学習データへの不正混入はデータポイズニング攻撃の説明。\n\n【頻出】AIセキュリティの4攻撃（敵対的攻撃・データポイズニング・モデル逆転・プロンプトインジェクション）とその目的・フェーズの対応関係を整理する。\n【関連】差分プライバシー（Differential Privacy）やフェデレーテッドラーニング（Federated Learning）はモデル逆転攻撃への対策技術として注目されている。"
