"explanation": "AIシステムのサプライチェーンリスクとは、AIシステムの開発・運用に使用する学習データ・オープンソースモデル・外部ライブラリ・クラウドサービス等の調達・利用経路（サプライチェーン）を通じて、脆弱性・バックドア・不正コード・汚染データが混入するリスク。データポイズニングもその一形態。\n\nA：物理的な物流リスクはサプライチェーンリスクの一般概念だが、AIシステム文脈では情報・ソフトウェアの調達経路リスクを指す。\nC：これは調達コストリスク・財務リスクの説明であり、セキュリティのサプライチェーンリスクとは異なる。\nD：これはベンダーロックインリスク・事業継続リスク（BCP）の説明。\n\n【頻出】AIシステムのサプライチェーンリスクはソフトウェアセキュリティの観点から重要。オープンソースモデル・学習データ・外部依存ライブラリそれぞれのリスクを理解する。\n【関連】SBOM（ソフトウェア部品表）によるソフトウェアコンポーネントの可視化はサプライチェーンリスク管理の手法として注目されている。"
