"explanation": "特徴量エンジニアリングとは、機械学習モデルの性能を高めるために、生データ（数値・テキスト・画像等）から有効な特徴量（変数）を作成・選択・変換・正規化する前処理工程。ドメイン知識と統計的分析を組み合わせて行うデータサイエンスの中核スキル。\n\nB：誤り。深層学習は特徴抽出を自動化できる面があるが、前処理・特徴量設計が不要になったわけではない。データのクリーニング・正規化などは依然として重要。\nC：これは評価データセット作成の説明であり、特徴量エンジニアリングとは別工程。\nD：これはハイパーパラメータチューニング（グリッドサーチ・ベイズ最適化等）の説明。\n\n【頻出】機械学習パイプラインの工程（データ収集→前処理→特徴量エンジニアリング→学習→評価→デプロイ）の各段階の役割は基礎知識として問われる。\n【混同注意】特徴量エンジニアリング（人間が設計）と特徴表現学習（モデルが自動抽出、主に深層学習）は異なるアプローチ。深層学習の普及で後者の重要性が増しているが、前者も実務では不可欠。"
