"answer": 0,
"explanation": "転移学習とは、大規模データで学習した既存モデル（事前学習モデル）が獲得した知識・重みを、異なるが関連性のある新タスクに流用する手法。ゼロから学習するより少ないデータと計算リソースで高性能が得られる。LLMのファインチューニングも転移学習の一形態。\n\nB：分散学習はデータ・計算を複数機で分担して並列処理する手法。転移学習とは目的・手法が異なる。\nC：モデルの商業的なライセンス提供はビジネスモデルの話であり、技術的な転移学習の定義に当たらない。\nD：推薦システムへのデータ転用はドメイン適応に関連する話だが、転移学習の一般的定義の説明としては不正確。\n\n【頻出】転移学習は事前学習→ファインチューニングの文脈でLLMと密接に関連する概念。「大規模データで学習した汎用的な表現を特定タスクに活用」という流れを理解する。\n【関連】ドメイン適応（Domain Adaptation）・マルチタスク学習（Multi-task Learning）も転移学習ファミリーの関連概念として整理しておく。"
