"explanation": "アノテーションとは、機械学習の教師あり学習に使用する訓練データに対して、人間が正解ラベル・境界ボックス・感情タグ・エンティティタグ等の情報を付与する作業。データアノテーションの質と量がモデル精度に直接影響する。クラウドソーシング・専門アノテーターが担う。\n\nA：モデルのパラメータ削減・軽量化はプルーニング（枝刈り）・量子化（Quantization）の説明。\nC：コンテンツへの著作権・出典情報の付加はメタデータ管理・電子透かしの話であり、アノテーションの定義に当たらない。\nD：ソースコードへのコメント記述はプログラミングの慣習であり、機械学習のアノテーションとは異なる。\n\n【頻出】アノテーションはAI開発の「データ準備フェーズ」の核心作業。質の高いアノテーションデータがAIの性能を左右することを理解する。\n【関連】RLHFで使用する「人間のフィードバック」もアノテーションの一形態。AIの出力を人間が評価・ランク付けすることで、モデルを人間の好みに沿って調整する。"
