"特徴量の値域・スケールをそろえることで、勾配降下法の収束速度の向上や特定特徴量への過度な依存を防ぐ前処理手法をいう",
"正規化とはテストデータを正規分布に従う乱数で置き換えることでプライバシーを保護するデータ匿名化手法をいう",
