"answer": 1,
"explanation": "ハイパーパラメータとは、モデルの学習アルゴリズムの挙動を制御するために学習開始前に人間が設定するパラメータ。学習率（Learning Rate）・バッチサイズ・エポック数・ネットワークの層数・正則化係数などが代表例。データから自動学習されず、人間またはハイパーパラメータ最適化ツールが設定する。\n\nA：データから自動最適化されるのは「モデルパラメータ（重み・バイアス）」であり、ハイパーパラメータとは区別される。\nC：分類閾値は予測結果の後処理に関わる設定値であり、ハイパーパラメータの代表的説明には当たらない。\nD：データ量はデータセットの特性であり、ハイパーパラメータの定義に当たらない。\n\n【頻出】モデルパラメータ（学習で更新）とハイパーパラメータ（学習前に設定）の区別は機械学習の基本知識として頻出。\n【関連】ハイパーパラメータ最適化手法としてグリッドサーチ・ランダムサーチ・ベイズ最適化（Optuna等）があり、AutoMLの重要コンポーネントでもある。"
