"explanation": "LoRA（Low-Rank Adaptation）は、事前学習済みモデルの重み行列を凍結したまま、追加する低ランク（Low-Rank）の行列ペアのみを学習することで、フルファインチューニングの数百〜数千分の一のパラメータ数で高い適応性能を実現するPEFT（パラメータ効率的ファインチューニング）手法。\n\nB：低解像度入力による速度向上は画像処理・推論最適化の説明であり、LoRAの定義に当たらない。\nC：低評価回答の除外フィルタリングはモデルアンサンブル・ランキング手法の説明。\nD：低精度数値への変換は量子化（Quantization）の説明。LoRAとは別のモデル圧縮手法。\n\n【頻出】LoRA・QLoRA（量子化+LoRA）はAIの民主化文脈で個人・中小企業によるモデルカスタマイズを可能にした重要技術として出題される。\n【関連】PEFT（Parameter-Efficient Fine-Tuning）ファミリーにはLoRA・Prefix Tuning・Prompt Tuningなど複数の手法がある。LoRAが最も広く実用されている。"
