"explanation": "BLEU（Bilingual Evaluation Understudy）スコアは、機械翻訳の出力文と人間が作成した参照翻訳文のn-gram（連続するn個のトークン）の一致率を計算して翻訳品質を自動評価する指標。0〜1（または0〜100）のスコアで表され、1に近いほど参照翻訳と一致している。\n\nB：1秒間のトークン処理数はスループット・推論速度の評価指標（tokens/sec）であり、BLEUスコアとは異なる。\nC：人間評価者による5段階採点はMOS（Mean Opinion Score）評価の説明。BLEUは自動評価指標である点が重要な違い。\nD：翻訳精度と速度のトレードオフを表す多目的指標はBLEUの定義に当たらない。\n\n【頻出】BLEUスコアはNLP評価の代表的な自動評価指標として問われる。「n-gramの一致率」という計算原理と、自動評価指標であることを押さえる。\n【混同注意】BLEUはn-gramの適合率（Precision）ベース。ROUGEは要約評価に使われる再現率（Recall）ベースの指標。用途（翻訳 vs 要約）と方向（適合率 vs 再現率）で区別する。"
