"explanation": "貪欲探索（Greedy Decoding）は各ステップで最も高確率のトークンを選択し続ける最もシンプルな戦略。速いが最適解が得られないことがある。ビームサーチ（Beam Search）はビーム幅の数だけ候補シーケンスを保持して並列に探索し、最終的に最も高スコアのシーケンスを選ぶ。\n\nB：過去のトークンを参照して一括生成するのはデコーディング戦略の説明として不正確。自己回帰的な逐次生成が基本的な仕組み。\nC：誤り。デコーディング戦略はテキスト生成（推論）フェーズに適用される。学習フェーズとは別のプロセス。\nD：誤り。ビーム幅を大きくするほど探索空間が広がり計算コストが増加するため、生成速度は低下する傾向がある。\n\n【頻出】デコーディング戦略（貪欲探索・ビームサーチ・Top-k・Top-pサンプリング）はLLMの生成プロセス理解の基礎として問われる。\n【混同注意】Temperatureパラメータはサンプリングの確率分布を制御し、ビームサーチは候補シーケンスの探索方法を制御する。両者は独立した制御要素。"
