"explanation": "勾配降下法は損失関数L(θ)のパラメータθに対する勾配∂L/∂θを計算し、その反対方向（損失が減少する方向）に学習率αの分だけパラメータを更新する操作（θ ← θ - α・∂L/∂θ）を繰り返すことで損失を最小化する最適化アルゴリズム。深層学習の学習の根幹。\n\nB：精度・F値の最大化方向へのパラメータ更新という説明は誤り。勾配降下法は微分可能な損失関数（クロスエントロピー等）の最小化を行う。精度・F値は微分不可能。\nC：データを損失順に並べ替える手法はカリキュラム学習（Curriculum Learning）に関連するが、勾配降下法の定義ではない。\nD：全探索による最良解の選択は組み合わせ最適化（ブルートフォース探索）の説明であり、勾配ベースの手法とは根本的に異なる。\n\n【頻出】勾配降下法・SGD（確率的勾配降下法）・ミニバッチ勾配降下法・Adam等の最適化手法は機械学習の学習プロセス理解の核心として頻出。\n【関連】バックプロパゲーション（誤差逆伝播法）は勾配を効率的に計算するアルゴリズムであり、勾配降下法と組み合わせて深層学習の学習を実現する。"
