"explanation": "コサイン類似度は、二つのベクトルAとBのなす角θのコサイン値（cos θ = A·B / (|A||B|)）で類似度を測る指標。−1（完全に逆方向）から1（完全に同方向）の範囲をとり、0は直交（無関係）を意味する。ベクトルのEmbeddingを使った意味的類似性の計算でRAGシステム等に広く使われる。\n\nB：ユークリッド距離を正規化した指標の説明はコサイン類似度の定義と異なる。また「大きいほど距離が遠い」も逆。\nC：確率分布間の差異を測る指標はKLダイバージェンス（KL Divergence）の説明。損失関数としてはクロスエントロピーが主に使われる。\nD：コサイン変換・画像の周波数解析はDCT（離散コサイン変換）の説明であり、コサイン類似度とは全く異なる。\n\n【頻出】コサイン類似度はベクトルデータベース・意味検索・Embeddingの類似度計算の基礎として頻出。「角度ベースの類似度、−1〜1」が定義の核心。\n【関連】RAGシステムでユーザーの質問Embeddingと文書Embeddingのコサイン類似度を計算して関連文書を検索する処理が標準的に行われている。"
