"answer": 0,
"explanation": "LLM-as-a-Judgeとは、GPT-4やClaudeなどの高性能LLMを評価者（審査員）として活用し、別のLLMが生成したテキストの正確性・有用性・流暢さ・安全性等を自動的にスコアリング・評価する手法。人間評価の代替・補完として大規模な評価を効率化できる。MT-BenchやChatbotArenaでの活用が代表例。\n\nB：裁判所の判決文生成という説明はLLM-as-a-Judgeの「Judge（審査員）」という語に引きずられた誤解。法律専用評価ツールではない。\nC：第三者認証機関による公式認定はLLM-as-a-Judgeの定義に当たらない。\nD：訓練データとの照合による一致率計算はBLEU等の参照ベース評価であり、LLM-as-a-Judgeとは異なる手法。\n\n【頻出】LLM評価手法（自動評価指標・人間評価・LLM-as-a-Judge）の違いと使い分けは近年の評価研究の重要トピックとして出題される。\n【関連】LLM-as-a-Judgeの課題として、評価LLM自身のバイアス（自社モデルへの優遇・長い回答への過大評価等）が指摘されており、評価の信頼性確保が研究課題となっている。"
