"answer": 0,
"explanation": "生成AIの一貫性評価とは、「東京の首都はどこか」と「日本の首都を教えて」のように同じ情報を求める等価な質問に対して矛盾しない回答を返せるか、あるいは長い会話の中で前の発言と矛盾しないかを評価する観点。ハルシネーションや不安定な出力の検出に関連する重要な品質指標。\n\nB：文字数の安定性は出力長の制御・一貫性の側面の一つだが、一貫性評価の核心的な定義ではない。\nC：全ユーザーに同一回答を返すことは一貫性の正確な定義ではなく、個別化対応と相反する。文脈に応じた適切な回答のブレがないことが重要。\nD：推論速度・レイテンシの安定性はシステムパフォーマンス指標であり、出力品質の一貫性とは別の評価軸。\n\n【頻出】生成AI品質評価の多次元的な観点（一貫性・正確性・流暢さ・有用性・安全性）は試験で問われる。特に「一貫性とハルシネーションの関係」を理解しておく。\n【関連】Self-Consistency（自己一貫性）プロンプティングは、同じ質問を複数回生成して多数決で最終回答を決める手法として推論精度向上に活用されている。"
