"answer": 0,
"explanation": "グラウンドトゥルース（Ground Truth）とは、機械学習・AI評価において「正解」として採用される信頼できるデータ・ラベルのこと。モデルの予測精度評価・訓練データのラベル付けの基準として使われる。人間のアノテーターが付与したラベルや、専門家が確認した正解データが代表例。\n\nB：地上センサーデータのみを使う推論はグラウンドトゥルースの定義に当たらない。「グラウンド」は「地上」ではなく「根拠・基準」の意味。\nC：衛星画像と地上写真の照合はリモートセンシング分野でのグラウンドトゥルースの一使用例だが、AI評価全般の定義ではない。\nD：損失関数の最小化プロセスは最適化の説明であり、グラウンドトゥルースの定義に当たらない。\n\n【頻出】グラウンドトゥルースはAI評価・アノテーションの基礎語として頻出。「モデルが合わせるべき正解基準」という役割を押さえる。\n【関連】グラウンドトゥルースの品質（アノテーターの一致率・専門家監修の有無）がモデルの性能上限を決定づけるため、「ゴミイン・ゴミアウト（GIGO）」の原則と合わせて理解する。"
