"explanation": "評価データセットの汚染（Data Contamination）とは、LLMの性能評価に使用するベンチマークの問題・回答が事前学習データに含まれていることで、モデルが実質的に「答えを覚えた状態」でテストを受けるため評価スコアが実際の能力より高く見えてしまう問題。公正なベンチマーク比較を困難にする。\n\nB：訓練データへの有害・誤情報の混入はデータポイズニング・データ品質問題の説明。評価データセットの汚染とは文脈が異なる。\nC：競合他社へのモデル能力漏洩はモデル抽出攻撃・知的財産保護の話であり、汚染問題とは異なる。\nD：アノテーターの主観的偏りはアノテーションバイアスの問題であり、評価データ汚染の定義に当たらない。\n\n【頻出】ベンチマーク汚染はLLM評価の信頼性問題として近年注目されており、試験でも問われる重要トピック。「記憶vs実力」という問題の本質を理解する。\n【関連】汚染対策として、継続的に新しいベンチマークを作成する・プライベートベンチマークを使用する・汚染の有無を事前に検査する手法が研究されている。"
