"explanation": "NIST AI RMF（2023年公開）は米国国立標準技術研究所が策定したAIリスク管理のための自発的なフレームワーク。①GOVERN（ガバナンス体制の確立）②MAP（リスクの特定・文脈化）③MEASURE（リスクの測定・評価）④MANAGE（リスクへの対応）の4機能で構成され、組織が責任あるAI開発・運用を実践するための指針として広く参照されている。\n\nB：ISO/IEC 42001等のAI管理システム規格はISOが策定しているが、NISTのRMFとは別の機関・文書。また「強制適用」の国際標準ではなく任意適用が基本。\nC：EU AI規則の実施細則はEU機関（欧州委員会・ENISA等）が策定するものであり、NISTのフレームワークとは異なる。\nD：国連安全保障理事会による軍事AI条約の実施フレームワークはNIST AI RMFの定義に当たらない。\n\n【頻出】NIST AI RMFの4機能（GOVERN・MAP・MEASURE・MANAGE）とその目的は国際フレームワーク知識として頻出。EU AI規則との比較（任意 vs 法的義務）も整理する。\n【関連】日本企業がNIST AI RMFを参照してAIガバナンス体制を構築するケースが増えており、実務的な参照フレームワークとして重要性が高まっている。"
