"explanation": "AIインシデントデータベース（AIID）はPartnership on AI等が運営する、実世界でAIシステムが関与した問題・被害・失敗事例（採用AIによる差別・自動運転事故・顔認識の誤検知等）を体系的に収集・公開するデータベース。AI安全性研究・リスク評価・再発防止策の検討に活用される。\n\nB：サイバー攻撃のみを記録する説明はAIIDの定義を大幅に限定したものであり誤り。AIIDは技術的問題・社会的被害等広範なインシデントを収集する。\nC：学習エラー・収束失敗等の開発中の技術的障害はAIIDの収集対象の中心ではなく、実世界での被害・問題が主対象。\nD：政府の認証管理システムはAIIDの定義に当たらない。AIIDは研究機関・市民社会が運営する独立したデータベース。\n\n【頻出】AIインシデントデータベースはAIの実害事例の把握とリスク管理の観点から試験で問われる。「過去の失敗から学ぶ」安全性研究の重要なリソース。\n【関連】AIIDに記録された事例を分析することで、AI導入前のリスクアセスメント・ユースケース別リスク把握に活用できる実用的なリソースとして企業・研究者に利用されている。"
