"explanation": "標準的なニューラルネットワークは①入力層（特徴量を受け取る）②一つ以上の隠れ層（特徴の変換・抽象化を行う）③出力層（最終的な予測・分類結果を出力）の三種類の層で構成される。各層のニューロン間の結合には重みパラメータがあり、バックプロパゲーションと勾配降下法で学習される。\n\nB：誤り。深層学習（Deep Learning）の「深層」とは隠れ層が複数ある多層構造を指す。隠れ層の追加は表現能力の向上に貢献する（過学習対策は別途必要）。\nC：誤り。ニューラルネットワークは生物の神経細胞から着想を得た数学的モデルであり、電気化学信号を処理する生物学的ニューロンとは根本的に異なる。\nD：誤り。現代の深層学習モデルは数十〜数百層（ResNetは100層以上、GPT-4は数百億パラメータの多層構造）であり、3層制限は誤り。\n\n【頻出】ニューラルネットワークの基本構造（三層構成・重みの学習）は機械学習基礎の総復習として出題される。「隠れ層の役割」と「深層学習＝多層NN」の関係を整理する。\n【関連】活性化関数（ReLU・Sigmoid・Tanh等）は各層で非線形変換を行い、多層ネットワークの表現能力を高める重要なコンポーネント。"
