"explanation": "OECD AI原則・EU AI規則・各国のAI倫理ガイドライン等で共通して言及される主要な倫理原則：①公平性（Fairness）：差別・偏見のないAI②透明性（Transparency）：仕組みの適切な開示③説明可能性（Explainability）：意思決定根拠の説明④プライバシー保護（Privacy）：個人情報の適切な取り扱い⑤アカウンタビリティ（Accountability）：責任の明確化。これらは責任あるAI実践の基盤として国際的に共有されている。\n\nB：速度・精度等はシステム性能指標であり倫理原則ではない。\nC：収益性・競争優位性等はビジネス目標であり倫理原則ではない。\nD：自律性・自己複製等はAIシステムの危険な特性として懸念される方向性であり、倫理的設計の要件として推奨されるものではない。\n\n【頻出】AI倫理5大原則のセットは試験全体を通じた核心知識として繰り返し問われる。「性能指標」や「ビジネス目標」と「倫理原則」を明確に区別することが重要。\n【関連】安全性（Safety）・堅牢性（Robustness）・インクルージョン（Inclusion）を加えて7〜8原則として論じる機関もあり、文脈に応じた理解が求められる。"
