"explanation": "生成AIの出力品質は複数の要因の複合的な影響を受ける：①モデルの能力（アーキテクチャ・規模・学習方法）②訓練データの質・量・多様性③プロンプトの設計（具体性・文脈・指示の明確さ）④Temperatureやtop-pなどの推論時パラメータ⑤RAGや外部ツールの活用等。これらの組み合わせが最終的な出力品質を決定する。\n\nB：誤り。APIのレイテンシ（応答速度）は出力の速さに影響するが、出力コンテンツの品質（正確さ・有用さ・安全性）を決定するのは上記の複合要因。\nC：誤り。同じパラメータ数でも訓練データ・学習方法・アーキテクチャの工夫によって品質は大きく異なる。\nD：誤り。Temperature>0の設定では確率的サンプリングが行われるため、同一プロンプトに対して毎回全く同一の出力が生成される保証はない。\n\n【頻出】出力品質の複合的な決定要因（モデル・データ・プロンプト・パラメータ）の理解は実践スキルの総まとめとして問われる。「一要因のみで決まる」という単純化した選択肢は常に誤り。"
