"explanation": "AIの透明性報告書とは、AI企業が自主的または規制対応として定期的に公開するドキュメントで、AIシステムの設計方針・学習データの概要・安全性・公平性評価の結果・コンテンツポリシーの適用実績・誤用・悪用事例とその対応等を開示することで、ステークホルダーへのアカウンタビリティを実践する文書。OpenAI・Google・Meta等が公開している。\n\nB：AIが作成する財務報告書（決算書）は透明性報告書の定義に当たらない。\nC：誤り。透明性報告書の作成・公開が全世界で法的義務として確立しているわけではない。EU AI規則で一部義務化されつつあるが、自主開示も多い。\nD：誤り。ソースコード・全訓練データの完全公開は透明性報告書の一般的な要件ではなく、知的財産・プライバシーの観点から概要・サマリーレベルの開示が標準的。\n\n【頻出】透明性報告書はAI倫理・アカウンタビリティの実践ツールとして問われる。「法的義務ではなく自主開示が中心」という現状と、EU AI規則による義務化の方向性を理解する。\n【関連】モデルカードはモデル単位の透明性文書、透明性報告書はサービス・企業レベルの開示文書という階層関係で整理しておくと理解しやすい。"
