"explanation": "XAI（説明可能なAI）の代表的な技術手法：①SHAP（SHapley Additive exPlanations）：各特徴量の予測への貢献度を計算②LIME（Local Interpretable Model-agnostic Explanations）：局所的な線形近似モデルで予測根拠を説明③アテンション可視化：Transformerがどのトークンに注目したかを可視化④反事実的説明（Counterfactual Explanation）：「何が違えば別の結果になったか」を提示。\n\nB：誤り。SHAP・LIME等のXAI技術は実際に多くのモデルの説明責任実現に貢献しており、手動文書化が唯一の方法ではない。\nC：誤り。XAI技術によっても深層学習の内部動作の完全な解明は困難であり、提供できる説明は近似・局所的なものが多い。「100%正確な説明が可能」は誇張。\nD：誤り。SHAPはテキスト・画像・数値データを含む幅広いデータ形式に対応可能であり、テキストや数値データへの適用も実際に行われている。\n\n【頻出】XAIの技術手法（SHAP・LIME・アテンション可視化）は説明可能性の実現手段として問われる。各手法の適用範囲と限界を理解する。\n【関連】医療診断・与信審査・採用選考等の高リスクAI応用でのXAI活用は、EU AI規則・GDPR等が求める説明責任の技術的実現手段として実務での重要性が高まっている。"
