"explanation": "AIとSDGsの関係は両面的：貢献の例：気候モデリング（SDG13・気候変動）・遠隔医療AI（SDG3・健康）・AIチューター（SDG4・教育）・精密農業（SDG2・飢餓撲滅）・再生可能エネルギー管理最適化（SDG7・エネルギー）等。課題の例：AI学習・推論の大量電力消費（SDG13への負荷）・AI格差による不平等拡大（SDG10）・プライバシーリスク（SDG16）等。\n\nB：誤り。UNDP・UNEP等の国連機関もAIとSDGsの関係を積極的に分析・政策提言しており、正負両方向の影響が認められている。\nC：誤り。AIの活用でSDGsが自動的に全て達成されるという保証は存在しない。AIは強力なツールだが人間の意思決定・政策・行動変容との組み合わせが必要。\nD：誤り。グリーンAI（効率的なAI設計・再生可能エネルギー利用）やAIによるエネルギー効率化（スマートグリッド等）への貢献もあり、「必ずSDG13に反する」は誤り。\n\n【頻出】AIとSDGsの関係は「貢献と課題の両面」で理解することが重要。一方的な楽観・悲観は誤りというパターンが試験全体を通じた一貫したメッセージ。\n【関連】AI for Good（AIを社会課題解決に活用するITU主催の国際フォーラム）はAIとSDGsの連携を推進する代表的な国際的取り組みとして整理しておく。"
