"explanation": "LLMの知識カットオフ問題（学習データの時間的限界による最新情報の欠如）への主な対処法：①RAG（外部知識ベースやリアルタイム検索から最新情報を取得）②Webブラウジング機能（ChatGPT・Perplexity等）③ユーザーが最新情報をプロンプトに含める（In-context 情報提供）④定期的なモデルの再学習・継続学習。\n\nB：誤り。RAG・Web検索等の実用的な対処法が既に存在し、広く活用されている。諦める必要はない。\nC：誤り。パラメータ数を増やしてもカットオフ日以降の情報は学習されておらず、モデルサイズによるカットオフ問題の解決は不可能。\nD：誤り。Temperatureは出力の確率的な多様性を制御するパラメータであり、カットオフ問題（学習データの時間的制限）とは無関係。\n\n【頻出】カットオフ問題とRAGの関係は試験全体を通じた重要テーマ。複数の対処法とそれぞれの仕組みを理解する。\n【関連】「Retrieval-Augmented Generation」はカットオフ問題とハルシネーション問題の両方を緩和できる実用的な手法として企業AI導入で最も普及したアーキテクチャとなっている。"
